#!/usr/bin/env python3
import sys

INF = 100000000
def solve(H: int, W: int, c: "List[List[int]]", A: "List[List[int]]"):

    V = 10
    # WF
    # c = [[INF] * (V) for i in range(V)]
    for k in range(V):
        for i in range(V):
            if c[i][k] == INF : continue
            for j in range(V):
                if c[k][j] == INF: continue
                c[i][j] = min(c[i][j], c[i][k]+c[k][j])

    ans = 0
    for i in range(H):
        for j in range(W):
            if(A[i][j] != -1):
                ans += c[A[i][j]][1]
    
    print(ans)
    return


# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    H = int(next(tokens))  # type: int
    W = int(next(tokens))  # type: int
    c = [ [ int(next(tokens)) for _ in range(9-0+1) ] for _ in range(9-0+1) ]  # type: "List[List[int]]"
    A = [ [ int(next(tokens)) for _ in range(W) ] for _ in range(H) ]  # type: "List[List[int]]"
    solve(H, W, c, A)

if __name__ == '__main__':
    main()
